Seed = [  "@mia.dances earned 10 coins watching an ad",  "@noodlecart spent 100 coins → 1,000 likes queued",  "@bytebasics earned 5 coins watching a video",  "@studio.forma spent 100 coins → 200 followers queued",  "@LeoTravels earned 10 coins watching an ad",  "@quiet.archive bought 1,200 coins",];// Loads the real YouTube IFrame Player API once and reuses it for every embed.let ytApiPromise = null;function loadYouTubeApi() {  if (typeof window === "undefined") return Promise.resolve(null);  if (window.YT && window.YT.Player) return Promise.resolve(window.YT);  if (ytApiPromise) return ytApiPromise;  ytApiPromise = new Promise((resolve) => {    const prevReady = window.onYouTubeIframeAPIReady;    window.onYouTubeIframeAPIReady = () => {      if (typeof prevReady === "function") prevReady();      resolve(window.YT);    };    if (!document.querySelector('script[src="https://www.youtube.com/iframe_api"]')) {      const tag = document.createElement("script");      tag.src = "https://www.youtube.com/iframe_api";      document.head.appendChild(tag);    }  });  return ytApiPromise;}// Embeds a real YouTube video and only credits "watched" seconds while it's actually// playing (tracked via the player's real onStateChange events) — pausing, seeking away,// or closing the tab stops the clock, same as it would for a genuine ad or video view.function RealVideoWatcher({ videoId, requiredSeconds, onComplete }) {  const hostRef = useRef(null);  const playerRef = useRef(null);  const intervalRef = useRef(null);  const doneRef = useRef(false);  const [elapsed, setElapsed] = useState(0);  const [playerReady, setPlayerReady] = useState(false);  useEffect(() => {    let cancelled = false;    loadYouTubeApi().then((YT) => {      if (cancelled || !YT || !hostRef.current) return;      playerRef.current = new YT.Player(hostRef.current, {        videoId,        playerVars: { rel: 0, modestbranding: 1 },        events: {          onReady: () => !cancelled && setPlayerReady(true),          o